// ═══ SEED FUNCTION ═══
async function main() {
  await mongoose.connect(MONGODB_URI);
  console.log("Connected to MongoDB");

  const db = mongoose.connection.db;
  const collection = db.collection("interactivecourses");

  const existing = await collection.findOne({ slug: "mastering-telemental-health" });
  if (!existing) {
    console.error("Course not found! Run Batch 1 first to create the course document.");
    process.exit(1);
  }

  // Append sections 5-13
  const result = await collection.updateOne(
    { slug: "mastering-telemental-health" },
    {
      $push: { sections: { $each: SECTIONS_5_TO_13 } },
      $set: {
        assessment: {
          questions: FINAL_ASSESSMENT.questions,
          passingScore: 80,
          maxAttempts: 3
        },
        updatedAt: new Date()
      }
    }
  );

  console.log(`Updated: ${result.modifiedCount} document(s)`);

  // Stats
  let totalWords = 0;
  let totalBlocks = 0;
  let kcs = 0;
  for (const section of SECTIONS_5_TO_13) {
    for (const block of section.contentBlocks) {
      totalBlocks++;
      if (block.type === "text" || block.type === "imageText") {
        const text = (block.content || "").replace(/<[^>]+>/g, " ");
        totalWords += text.split(/\s+/).filter(w => w).length;
      }
      if (block.type === "multipleChoice") kcs++;
    }
  }

  console.log("\n═══ BATCHES 2-4 STATISTICS ═══");
  console.log(`Sections added: ${SECTIONS_5_TO_13.length}`);
  console.log(`Content blocks: ${totalBlocks}`);
  console.log(`Knowledge checks: ${kcs}`);
  console.log(`Assessment questions: ${FINAL_ASSESSMENT.questions.length}`);
  console.log(`Text word count (this batch): ~${totalWords}`);

  await mongoose.disconnect();
  console.log("\nDone. Course now has all 13 sections + 20-question final assessment.");
}

main().catch(err => { console.error(err.message); process.exit(1); });
